<?php
namespace App\Policies;
use App\Models\{DesignPackageSubmission,User}; use App\Policies\Concerns\{CompanyOwnedPolicy,DesignOwnedPolicy};
class DesignPackageSubmissionPolicy { use CompanyOwnedPolicy,DesignOwnedPolicy; public function viewAny(User $u):bool{return $this->designCanCreate($u,'view_any_design_package_submission');} public function view(User $u,DesignPackageSubmission $r):bool{return $this->designCan($u,'view_design_package_submission',$r);} public function create(User $u):bool{return $this->designCanCreate($u,'create_design_package_submission');} public function update(User $u,DesignPackageSubmission $r):bool{return false;} public function delete(User $u,DesignPackageSubmission $r):bool{return false;} public function review(User $u,DesignPackageSubmission $r):bool{return $this->designCan($u,'review_design_submission',$r);} public function requestRevision(User $u,DesignPackageSubmission $r):bool{return $this->designCan($u,'request_design_revision',$r);} }
